    admin.push({ path: '/admin/dashboard', icon: Icons.dashboard, label: 'Dashboard' });
    admin.push({ path: '/admin/reports', icon: Icons.reports, label: 'Reportes' });
    admin.push({ path: '/admin/reservations', icon: Icons.reservations, label: 'Reservas' });
