// ═══════════════════════════════════════════════
//  SUB-COMPONENTES
// ═══════════════════════════════════════════════

// Link de navegación simple (PC)
function NavLink({ item }) {
  const navigate = useNavigate();
  const location = useLocation();
  const active = location.pathname === item.path || location.pathname.startsWith(item.path + '/');
  return (
    <button
      onClick={() => navigate(item.path)}
      style={{
        display: 'flex',
        alignItems: 'center',
        gap: 7,
        padding: '8px 16px',
        borderRadius: 10,
        border: 'none',
        background: active ? c.bgActive : 'transparent',
        color: active ? c.primary : c.textMuted,
        fontSize: 13.5,
        fontWeight: active ? 600 : 500,
        cursor: 'pointer',
        transition: 'all 0.2s ease',
        whiteSpace: 'nowrap',
      }}
      onMouseEnter={(e) => {
        if (!active) e.currentTarget.style.background = c.bgHover;
        e.currentTarget.style.color = c.primary;
      }}
      onMouseLeave={(e) => {
        if (!active) e.currentTarget.style.background = 'transparent';
        e.currentTarget.style.color = active ? c.primary : c.textMuted;
      }}
    >
      <span style={{ display: 'flex', opacity: 0.85 }}>{item.icon}</span>
      {item.label}
    </button>
  );
}

// Item dentro de dropdown (PC)
function DropdownItem({ item, isActive, navigate }) {
  const active = isActive(item.path);
  return (
    <button
      onClick={() => navigate(item.path)}
      style={{
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        padding: '10px 14px',
        borderRadius: 10,
        border: 'none',
        background: active ? c.bgActive : 'transparent',
        color: active ? c.primary : c.text,
        fontSize: 13,
        fontWeight: active ? 600 : 500,
        cursor: 'pointer',
        transition: 'all 0.15s',
        textAlign: 'left',
      }}
      onMouseEnter={(e) => {
        if (!active) e.currentTarget.style.background = c.bgHover;
      }}
      onMouseLeave={(e) => {
        if (!active) e.currentTarget.style.background = 'transparent';
      }}
    >
      <span style={{
        display: 'flex',
        color: active ? c.primary : c.textMuted,
      }}>
        {item.icon}
      </span>
      {item.label}
      {active && (
        <span style={{
          marginLeft: 'auto',
          width: 6,
          height: 6,
          borderRadius: '50%',
          background: c.primary,
        }}/>
      )}
    </button>
  );
}

// Item del sidebar (móvil)
function SidebarItem({ item, isActive, navigate }) {
  const active = isActive(item.path);
  return (
    <button
      onClick={() => navigate(item.path)}
      style={{
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        gap: 12,
        padding: '12px 16px',
        borderRadius: 10,
        border: 'none',
        background: active ? 'rgba(251,191,36,0.12)' : 'transparent',
        color: active ? c.sidebarTextActive : c.sidebarText,
        fontSize: 14,
        fontWeight: active ? 600 : 500,
        cursor: 'pointer',
        transition: 'all 0.2s',
        marginBottom: 2,
        textAlign: 'left',
      }}
    >
      <span style={{ display: 'flex', opacity: 0.8 }}>{item.icon}</span>
      {item.label}
      {active && (
        <span style={{
          marginLeft: 'auto',
          width: 6,
          height: 6,
          borderRadius: '50%',
          background: c.sidebarTextActive,
        }}/>
      )}
    </button>
  );
}

// Sub-item del sidebar (móvil)
function SidebarSubItem({ item, isActive, navigate }) {
  const active = isActive(item.path);
  return (
    <button
      onClick={() => navigate(item.path)}
      style={{
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        padding: '10px 14px 10px 18px',
        borderRadius: 8,
        border: 'none',
        background: active ? 'rgba(251,191,36,0.10)' : 'transparent',
        color: active ? c.sidebarTextActive : c.sidebarText,
        fontSize: 13,
        fontWeight: active ? 600 : 400,
        cursor: 'pointer',
        transition: 'all 0.2s',
        marginBottom: 2,
        textAlign: 'left',
        opacity: active ? 1 : 0.75,
      }}
    >
      <span style={{
        width: 5,
        height: 5,
        borderRadius: '50%',
        background: active ? c.sidebarTextActive : c.sidebarText,
        opacity: active ? 1 : 0.4,
        flexShrink: 0,
      }}/>
      {item.label}
    </button>
  );
}

export default DashboardLayout;
